using System;

namespace Contact.API.Helpers
{
    /// <summary>
    /// Фірмові константи бренду «Контакт» для звітів (PDF / Excel).
    /// Логотип вшито у вигляді Base64, щоб звіти не залежали від файлів на диску.
    /// </summary>
    public static class BrandAssets
    {
        // Палітра застосунку (узгоджена з dashboard.css / analytics.css)
        public const string Ink        = "#151C22"; // темна панель (фон логотипу)
        public const string InkSoft    = "#1B2630"; // темна панель (світліша)
        public const string Green      = "#00B712"; // основний бренд-зелений
        public const string GreenBright = "#30D73C"; // акцентний зелений
        public const string Blue       = "#1F8EE2"; // акцент (товари)
        public const string Violet     = "#9B6CF0"; // акцент (збірки)
        public const string Amber      = "#E2B81F"; // акцент (послуги)
        public const string Red        = "#E2706A"; // негатив
        public const string Ink2       = "#22303B"; // рамки
        public const string TextDark   = "#1B242B"; // основний текст
        public const string TextMuted  = "#6B7884"; // приглушений текст
        public const string RowAlt     = "#F4F7F9"; // парні рядки таблиць
        public const string HeadText   = "#FFFFFF";

        private const string LogoBase64 =
"";

        private static byte[]? _logo;

        /// <summary>JPEG-логотип «Контакт» (зелений на темному фоні), 614×120.</summary>
        public static byte[] Logo => _logo ??= Convert.FromBase64String(LogoBase64);

        public const double LogoAspect = 614.0 / 120.0;
    }
}
